package za.ac.rosebank.quickchat;
import java.nio.file.Path;
import java.util.Scanner;
public class Main {
 private static int readInt(Scanner s,String prompt){while(true){System.out.print(prompt);try{return Integer.parseInt(s.nextLine().trim());}catch(NumberFormatException e){System.out.println("Enter a valid number.");}}}
 public static void main(String[] args)throws Exception{Scanner in=new Scanner(System.in);System.out.println("NJABULO NDLOVU | QUICKCHAT");System.out.print("First name: ");String first=in.nextLine();System.out.print("Last name: ");String last=in.nextLine();System.out.print("Username: ");String user=in.nextLine();System.out.print("Password: ");String pass=in.nextLine();System.out.print("Your SA number (+27...): ");String phone=in.nextLine();Login login=new Login(first,last,user,pass,phone);System.out.println(login.registerUser());if(!login.isRegistered())return;System.out.print("Login username: ");String enteredUser=in.nextLine();System.out.print("Login password: ");String enteredPass=in.nextLine();login.loginUser(enteredUser,enteredPass);System.out.println(login.returnLoginStatus());if(!login.isAuthenticated())return;System.out.println("Welcome to QuickChat.");int limit;do{limit=readInt(in,"How many messages would you like to enter? ");}while(limit<0);int entered=0;boolean running=true;while(running){System.out.println("\n1) Send Messages\n2) Show recently sent messages\n3) Quit");int choice=readInt(in,"Choose: ");switch(choice){case 1:if(entered>=limit){System.out.println("Message limit reached.");break;}System.out.print("Recipient (+27...): ");String recipient=in.nextLine();System.out.print("Message: ");String text=in.nextLine();Message msg=new Message(entered,recipient,text);System.out.println(msg.messageIdGenerated());if(!msg.checkRecipientCell().equals("Cell phone number successfully captured.")){System.out.println(msg.checkRecipientCell());break;}if(!msg.checkMessageLength().equals("Message ready to send.")){System.out.println(msg.checkMessageLength());break;}System.out.println("1) Send Message\n2) Disregard Message\n3) Store Message to send later");int action=readInt(in,"Choose: ");if(action<1||action>3){System.out.println("Invalid option.");break;}System.out.println(msg.sentMessage(action));if(action==2){int confirm=readInt(in,"Press 0 to delete the message: ");if(confirm!=0){System.out.println("Deletion not confirmed; message remains discarded.");}}if(action==3){msg.storeMessage(Path.of("data","stored-messages.json"));}if(action==1)System.out.println(msg.printMessages());entered++;System.out.println("Total messages sent: "+Message.returnTotalMessages());break;case 2:System.out.println("Coming Soon.");break;case 3:running=false;break;default:System.out.println("Invalid option.");}}System.out.println("Total messages sent: "+Message.returnTotalMessages());System.out.println("Thank you for using QuickChat.");}
}
